-- 04_tasks_and_grants.sql: suspend task root, procedures, GRANTS FIRST, then tasks re-created SUSPENDED
-- GENERATED by backend/scripts/build_deploy_bundle.py from repo SQL. Do not edit; rebuild instead.
-- Paste into ONE Snowsight worksheet and use "Run all". Idempotent. Synthetic data only.
USE ROLE ACCOUNTADMIN;
USE SECONDARY ROLES NONE;
USE DATABASE SAARTHI;
USE WAREHOUSE SAARTHI_AI_WH;

-- N4-01: EXECUTED (not commented). A started task graph makes CREATE OR REPLACE TASK on a child fail.
-- IF EXISTS plus the handler make this a no-op on a fresh account. Resume is a deliberate manual step (step 08 tail).
EXECUTE IMMEDIATE $$
BEGIN
    ALTER TASK IF EXISTS SAARTHI.OPERATIONAL.TASK_PARSE_DOCUMENTS SUSPEND;
    RETURN 'TASK_PARSE_DOCUMENTS suspended (or absent)';
EXCEPTION
    WHEN OTHER THEN
        RETURN 'task suspend skipped: ' || SQLERRM;
END;
$$;

-- Round 6 (task dedupe): parse_documents_proc keys on DOCUMENT.source_path (stable stage path), not on etag.
-- ADD COLUMN IF NOT EXISTS is additive; no table is dropped. TASK_PARSE_DOCUMENTS itself is NOT re-created here
-- (setup.sql creates it, resolving its EXECUTE AS USER from practitioner PRAC-01); it stays suspended.
ALTER TABLE SAARTHI.DOCUMENTS.DOCUMENT ADD COLUMN IF NOT EXISTS source_path VARCHAR;

-- ===== BEGIN tasks/parse_documents.sql (procedure part) =====
-- =============================================================================
-- STEP 16a - TASK parse_documents (pulled forward - unstructured ingestion)
-- =============================================================================
-- WORK-PLAN.md Day 3-4. AI_PARSE_DOCUMENT(LAYOUT, page_split) -> DOCUMENT +
-- DOC_PAGE. Dedup on stage source_path (legacy fallback: etag) before parsing. The only place this
-- AI function may run is a Task (never a Dynamic Table - non-deterministic).
--
-- Scans DIRECTORY(@PATIENT_DOCS) for files not yet in DOCUMENT. Dedup key (Round 6, unverified-needs-deploy):
-- DOCUMENT.source_path = the stage relative_path, which is stable across runs. Rows loaded before source_path
-- existed are matched on file_hash = etag as a legacy fallback only. Never etag alone: bounded loaders store a
-- SHA-256 in file_hash, which can never equal a stage etag, so an etag-only key re-parses (paid) every staged
-- file. Rows this task inserts still store the stage etag in file_hash (a real SHA-256 needs a client-side read);
-- the dedupe does not depend on it. Backfills pre-existing files immediately;
-- DOC_STREAM (step 13) drives the same procedure for files arriving after
-- the stream's creation (e.g. a late addendum, mid-demo).
CREATE OR REPLACE PROCEDURE SAARTHI.OPERATIONAL.parse_documents_proc()
  RETURNS VARIANT
  LANGUAGE SQL
  COMMENT = 'Task body for parse_documents. AI_PARSE_DOCUMENT is the only AI function here - deterministic steps stay in DTs.'
  EXECUTE AS OWNER
AS
$$
DECLARE
    v_count INTEGER DEFAULT 0;
    v_relative_path VARCHAR;
    v_file_hash     VARCHAR;
    v_patient_id    VARCHAR;
    v_doc_id        VARCHAR;
    v_parsed        VARIANT;
    v_page_count    INTEGER;
    v_i             INTEGER;
    v_first_text    VARCHAR;
    v_doc_type      VARCHAR;
    v_type_count    INTEGER;
    v_reference_count INTEGER DEFAULT 0;
    v_run_id        VARCHAR DEFAULT UUID_STRING();
    -- A file is already ingested if a DOCUMENT row records its stage path (source_path)
    -- or, for rows from before that column, its etag. file_hash alone never matched:
    -- rows loaded by the bounded scripts hold a SHA-256, never an etag.
    c_new_files CURSOR FOR
        SELECT d.relative_path, d.etag,
               SPLIT_PART(d.relative_path, '/', 1) AS patient_id
          FROM DIRECTORY(@SAARTHI.STAGES.PATIENT_DOCS) d
         WHERE NOT EXISTS (
                 SELECT 1 FROM SAARTHI.DOCUMENTS.DOCUMENT doc
                  WHERE doc.scope = 'patient'
                    AND (doc.source_path = d.relative_path OR doc.file_hash = d.etag)
               );
    c_new_reference CURSOR FOR
        SELECT d.relative_path, d.etag
          FROM DIRECTORY(@SAARTHI.STAGES.REFERENCE_DOCS) d
         WHERE NOT EXISTS (
                 SELECT 1 FROM SAARTHI.DOCUMENTS.DOCUMENT doc
                  WHERE doc.scope = 'reference'
                    AND (doc.source_path = d.relative_path OR doc.file_hash = d.etag)
               );
BEGIN
    -- Internal-stage directory tables refresh only on demand, so an upload is invisible
    -- to DIRECTORY() and DOC_STREAM until refreshed. Uploaders refresh PATIENT_DOCS so
    -- the stream fires this task; refreshing here as well covers REFERENCE_DOCS, which
    -- has no stream.
    ALTER STAGE SAARTHI.STAGES.PATIENT_DOCS REFRESH;
    ALTER STAGE SAARTHI.STAGES.REFERENCE_DOCS REFRESH;
    -- Consume DOC_STREAM. The work list is DIRECTORY(), not the stream, but an unconsumed
    -- stream keeps SYSTEM$STREAM_HAS_DATA true and wakes this task every 5 minutes
    -- forever. The DML that consumes it doubles as the run's audit row.
    INSERT INTO SAARTHI.OPERATIONAL.INGESTION_RUN (run_id, source_id, records_received, file_hashes)
    SELECT :v_run_id, 'PATIENT_DOCS', COUNT(*), ARRAY_AGG(etag)
      FROM SAARTHI.DOCUMENTS.DOC_STREAM WHERE METADATA$ACTION = 'INSERT';
    OPEN c_new_files;
    FETCH c_new_files INTO v_relative_path, v_file_hash, v_patient_id;

    WHILE (v_relative_path IS NOT NULL) DO
        -- Re-fetched fresh here rather than trusted from the cursor FETCH
        -- above: verified live that the cursor-fetched value of a VARCHAR
        -- carried into a later INSERT inside this same loop body stayed
        -- pinned to the FIRST iteration's value on every subsequent
        -- iteration (all 4 DOCUMENT rows got file 1's etag) even though
        -- v_doc_id (assigned fresh via UUID_STRING() each iteration) and
        -- the AI_PARSE_DOCUMENT content were both correctly distinct per
        -- iteration. A fresh scalar SELECT immediately before the INSERT
        -- that consumes it avoids whatever caching caused that.
        SELECT etag INTO :v_file_hash
          FROM DIRECTORY(@SAARTHI.STAGES.PATIENT_DOCS) WHERE relative_path = :v_relative_path;

        v_parsed := (SELECT AI_PARSE_DOCUMENT(
                        TO_FILE('@SAARTHI.STAGES.PATIENT_DOCS', :v_relative_path),
                        {'mode':'LAYOUT', 'page_split': true}));
        v_page_count := (SELECT GET_PATH(:v_parsed, 'metadata.pageCount')::INTEGER);
        v_doc_id := UUID_STRING();
        -- Record unusable parses once as unreadable; retain exact page validation.
        IF (v_page_count IS NULL OR v_page_count<1 OR NOT COALESCE(IS_ARRAY(v_parsed:pages),FALSE)
            OR ARRAY_SIZE(v_parsed:pages)!=v_page_count) THEN
            INSERT INTO SAARTHI.DOCUMENTS.DOCUMENT
                (doc_id, patient_id, scope, doc_type, file_hash, source_path, ingested_at, ingestion_method, status)
            VALUES (:v_doc_id, :v_patient_id, 'patient', 'unknown', :v_file_hash, :v_relative_path,
                    CURRENT_TIMESTAMP(), 'downloaded_pdf', 'unreadable');
            v_count := v_count + 1;
            FETCH c_new_files INTO v_relative_path, v_file_hash, v_patient_id;
            CONTINUE;
        END IF;
        SELECT COUNT(DISTINCT value:index::INTEGER) INTO :v_type_count
          FROM TABLE(FLATTEN(input=>:v_parsed:pages))
         WHERE IS_INTEGER(value:index) AND value:index::INTEGER>=0
           AND value:index::INTEGER<:v_page_count AND IS_VARCHAR(value:content);
        IF (v_type_count!=v_page_count) THEN
            INSERT INTO SAARTHI.DOCUMENTS.DOCUMENT
                (doc_id, patient_id, scope, doc_type, file_hash, source_path, ingested_at, ingestion_method, status)
            VALUES (:v_doc_id, :v_patient_id, 'patient', 'unknown', :v_file_hash, :v_relative_path,
                    CURRENT_TIMESTAMP(), 'downloaded_pdf', 'unreadable');
            v_count := v_count + 1;
            FETCH c_new_files INTO v_relative_path, v_file_hash, v_patient_id;
            CONTINUE;
        END IF;
        v_first_text := NULL;
        SELECT value:content::VARCHAR INTO :v_first_text
          FROM TABLE(FLATTEN(input=>:v_parsed:pages)) WHERE value:index::INTEGER=0;
        -- Conservative explicit-heading routing, not a clinical classifier.
        -- Unknown/ambiguous headers stay unknown. No model call or filename guess.
        SELECT COUNT(DISTINCT h.doc_type),MIN(h.doc_type) INTO :v_type_count,:v_doc_type
          FROM TABLE(SPLIT_TO_TABLE(REPLACE(UPPER(:v_first_text),CHR(13),''),CHR(10))) line
          JOIN (SELECT column1 AS title,column2 AS doc_type FROM VALUES
            ('COMPLETE BLOOD COUNT','lab_report'),('LABORATORY REPORT','lab_report'),
            ('HISTOPATHOLOGY / HER2 REPORT','pathology_report'),('HISTOPATHOLOGY REPORT','pathology_report'),
            ('RADIOLOGY REPORT','imaging_report'),('DISCHARGE SUMMARY','discharge_summary'),
            ('AUTHORIZATION LETTER','authorization_letter'),('AUTHORISATION LETTER','authorization_letter'),
            ('PRESCRIPTION','prescription'),('CONSENT FORM','consent_form'),('REFERRAL LETTER','referral_letter')) h
            ON TRIM(line.value)=h.title WHERE line.index<=8;
        IF (v_type_count!=1) THEN v_doc_type:='unknown'; END IF;
        -- NULL means capture quality is unassessed (metadata, not clinical missingness).
        -- Clean extracted text cannot prove a clean image. Do not change the enum.
        INSERT INTO SAARTHI.DOCUMENTS.DOCUMENT
            (doc_id, patient_id, scope, doc_type, file_hash, source_path, source_quality, ingested_at, ingestion_method, status)
        VALUES
            (:v_doc_id, :v_patient_id, 'patient', :v_doc_type, :v_file_hash, :v_relative_path,
             NULL, CURRENT_TIMESTAMP(), 'downloaded_pdf', 'active');

        v_i := 0;
        WHILE (v_i < v_page_count) DO
            INSERT INTO SAARTHI.DOCUMENTS.DOC_PAGE (doc_id, page_index, text, char_count)
            SELECT :v_doc_id, :v_i,
                   GET_PATH(p.value, 'content')::VARCHAR,
                   LENGTH(GET_PATH(p.value, 'content')::VARCHAR)
              FROM TABLE(FLATTEN(input => GET_PATH(:v_parsed, 'pages'))) p
             WHERE p.value:index::INTEGER = :v_i;
            v_i := v_i + 1;
        END WHILE;

        v_count := v_count + 1;
        -- Was INTO ..., v_doc_id, ...: the etag landed in v_doc_id and v_file_hash kept
        -- the previous file's value, so dedupe could not hold across iterations.
        FETCH c_new_files INTO v_relative_path, v_file_hash, v_patient_id;
    END WHILE;
    CLOSE c_new_files;

    -- Reference corpus (R6): same shape as the patient loop but scope='reference',
    -- patient_id NULL, and stage is REFERENCE_DOCS. R6 keeps the two corpora in
    -- physically separate SEARCH SERVICES; a single parse task can populate both
    -- because scope on the DOCUMENT row is what routes each chunk to the right
    -- index (chunk_documents_proc copies d.scope into DOC_CHUNK.doc_scope).
    OPEN c_new_reference;
    FETCH c_new_reference INTO v_relative_path, v_file_hash;
    WHILE (v_relative_path IS NOT NULL) DO
        -- Same fresh SELECT etag pattern as the patient loop above,
        -- preserving the workaround for the cursor-value-pinning bug found live.
        SELECT etag INTO :v_file_hash
          FROM DIRECTORY(@SAARTHI.STAGES.REFERENCE_DOCS) WHERE relative_path = :v_relative_path;

        v_parsed := (SELECT AI_PARSE_DOCUMENT(
                        TO_FILE('@SAARTHI.STAGES.REFERENCE_DOCS', :v_relative_path),
                        {'mode':'LAYOUT', 'page_split': true}));
        v_page_count := (SELECT GET_PATH(:v_parsed, 'metadata.pageCount')::INTEGER);
        v_doc_id := UUID_STRING();

        INSERT INTO SAARTHI.DOCUMENTS.DOCUMENT
            (doc_id, patient_id, scope, doc_type, file_hash, source_path, source_quality, ingested_at, ingestion_method, status)
        VALUES
            (:v_doc_id, NULL, 'reference', 'clinical_guideline', :v_file_hash, :v_relative_path,
             NULL, CURRENT_TIMESTAMP(), 'downloaded_pdf', 'active');

        v_i := 0;
        WHILE (v_i < v_page_count) DO
            INSERT INTO SAARTHI.DOCUMENTS.DOC_PAGE (doc_id, page_index, text, char_count)
            SELECT :v_doc_id, :v_i,
                   GET_PATH(p.value, 'content')::VARCHAR,
                   LENGTH(GET_PATH(p.value, 'content')::VARCHAR)
              FROM TABLE(FLATTEN(input => GET_PATH(:v_parsed, 'pages'))) p
             WHERE p.value:index::INTEGER = :v_i;
            v_i := v_i + 1;
        END WHILE;

        v_reference_count := v_reference_count + 1;
        FETCH c_new_reference INTO v_relative_path, v_file_hash;
    END WHILE;
    CLOSE c_new_reference;

    -- Chunk in the same run so new pages reach Cortex Search; the stream-triggered chain
    -- otherwise never chunks (only the orchestrator did).
    CALL SAARTHI.OPERATIONAL.chunk_documents_proc();
    UPDATE SAARTHI.OPERATIONAL.INGESTION_RUN
       SET completed_at = CURRENT_TIMESTAMP(), records_loaded = :v_count + :v_reference_count
     WHERE run_id = :v_run_id;
    RETURN OBJECT_CONSTRUCT(
        'run_id', v_run_id,
        'documents_parsed', v_count,
        'reference_documents_parsed', v_reference_count
    );
END;
$$;
-- ===== END tasks/parse_documents.sql (procedure part) =====

-- ===== BEGIN tasks/reconcile_evidence.sql (procedure part) =====
-- =============================================================================
-- STEP 16d - TASK reconcile_evidence
-- =============================================================================
-- SPEC.md §12 / R7. Detects two cross-source conditions on the ASSERTION table:
--   (a) same-specimen disagreement -> mark verification_status = 'conflicting'
--   (b) different-specimen disagreement -> preserve verified findings and write
--       an EVIDENCE_LINK relation, keeping the seven-state missingness type.
--
-- Deterministic; no AI. Runs downstream of extract_assertions so it sees a
-- coherent pass1/pass2 pair. Idempotent via MERGE - re-running produces the
-- same tagging without duplicates.

CREATE OR REPLACE PROCEDURE SAARTHI.OPERATIONAL.reconcile_evidence_proc()
  RETURNS VARIANT
  LANGUAGE SQL
  COMMENT = 'Task body for reconcile_evidence. Cross-source discordance detection over ASSERTION.'
  EXECUTE AS OWNER
AS
$$
DECLARE
    v_same_spec_conflicts INTEGER DEFAULT 0;
    v_cross_spec_discordant INTEGER DEFAULT 0;
    v_links INTEGER DEFAULT 0;
BEGIN
    -- Same-specimen disagreement: two ASSERTION rows share (subject, predicate,
    -- specimen_id via source doc) but disagree on value. Uses pass1_value <>
    -- pass2_value as the direct R7 conflict signal. Missing specimen link
    -- (both NULL) means we treat the subject+predicate pair as one specimen.
    MERGE INTO SAARTHI.EVIDENCE.ASSERTION t
    USING (
        SELECT a.assertion_id
          FROM SAARTHI.EVIDENCE.ASSERTION a
         WHERE a.pass1_value IS NOT NULL
           AND a.pass2_value IS NOT NULL
           AND a.pass1_value <> a.pass2_value
           AND a.verification_status = 'verified'
    ) s
    ON t.assertion_id = s.assertion_id
    WHEN MATCHED THEN UPDATE SET t.verification_status = 'conflicting';

    v_same_spec_conflicts := SQLROWCOUNT;

    -- Different documents alone do not establish different specimens. Require
    -- distinct recorded accession IDs for the same patient and concept; missing
    -- accession IDs contribute no inferred cross-specimen relation.
    MERGE INTO SAARTHI.EVIDENCE.EVIDENCE_LINK t
    USING (
        SELECT DISTINCT a1.assertion_id, a2.assertion_id AS target_id
          FROM SAARTHI.EVIDENCE.ASSERTION a1
          JOIN SAARTHI.EVIDENCE.ASSERTION a2
            ON a1.concept_id = a2.concept_id
           AND a1.doc_id <> a2.doc_id
           AND a1.value <> a2.value
           -- Qualitative findings may legitimately have no unit in either read.
           AND EQUAL_NULL(a1.unit, a2.unit)
           AND a1.verification_status = 'verified'
           AND a2.verification_status = 'verified'
          JOIN SAARTHI.DOCUMENTS.DOCUMENT d1 ON d1.doc_id = a1.doc_id
          JOIN SAARTHI.DOCUMENTS.DOCUMENT d2 ON d2.doc_id = a2.doc_id
          -- Only specimen-bound concepts (biomarkers: HER2 IHC/FISH ...) can be discordant
          -- across specimens. A serial analyte (Hb 10.1 then 11.2) is a trend, not a discordance.
          JOIN SAARTHI.OPERATIONAL.CLINICAL_ONTOLOGY co
            ON co.concept_id = a1.concept_id AND co.concept_type = 'biomarker'
         WHERE a1.missingness_state = 'present'
           AND a2.missingness_state = 'present'
           AND d1.patient_id = d2.patient_id
           AND d1.scope = 'patient' AND d2.scope = 'patient'
           AND d1.status = 'active' AND d2.status = 'active'
           AND d1.accession_id <> d2.accession_id
           AND LENGTH(TRIM(d1.accession_id)) > 0
           AND LENGTH(TRIM(d2.accession_id)) > 0
    ) s
    ON t.assertion_id = s.assertion_id AND t.target_id = s.target_id
       AND t.target_type = 'assertion' AND t.relation = 'discordant_across_specimens'
    WHEN NOT MATCHED THEN INSERT (assertion_id, target_type, target_id, relation)
        VALUES (s.assertion_id, 'assertion', s.target_id, 'discordant_across_specimens');

    v_cross_spec_discordant := SQLROWCOUNT;

    -- Provenance: a verified numeric assertion SUPPORTS a structured event only when
    -- exactly one event of the same patient and concept, on the source document's
    -- effective date, carries the same number and exact unit (digit separators ignored, so the
    -- Indian "2,60,604" equals 260604). Ambiguity or mismatch writes no link -
    -- provenance is never guessed. Non-numeric results (HER2 IHC text) are not linked.
    MERGE INTO SAARTHI.EVIDENCE.EVIDENCE_LINK t
    USING (
        SELECT a.assertion_id, MIN(ce.event_id) AS event_id
          FROM SAARTHI.EVIDENCE.ASSERTION a
          JOIN SAARTHI.DOCUMENTS.DOCUMENT d
            ON d.doc_id = a.doc_id AND d.scope = 'patient' AND d.status = 'active'
          JOIN SAARTHI.CORE.CLINICAL_EVENT ce
            ON ce.patient_id = d.patient_id
           AND ce.concept_id = a.concept_id
           AND ce.event_time::DATE = d.effective_at::DATE
           AND ce.value_num = TRY_TO_DOUBLE(REPLACE(a.value, ',', ''))
           -- Equal numbers in different or unknown units are not corroboration.
           -- Unit conversion belongs to the existing normalization rules.
           AND a.unit = ce.unit
         WHERE a.verification_status = 'verified'
           AND a.missingness_state = 'present'
           AND TRY_TO_DOUBLE(REPLACE(a.value, ',', '')) IS NOT NULL
         GROUP BY a.assertion_id
        HAVING COUNT(*) = 1
    ) s
    ON t.assertion_id = s.assertion_id AND t.target_type = 'clinical_event'
       AND t.target_id = s.event_id AND t.relation = 'supports'
    WHEN NOT MATCHED THEN INSERT (assertion_id, target_type, target_id, relation)
        VALUES (s.assertion_id, 'clinical_event', s.event_id, 'supports');

    v_links := SQLROWCOUNT;

    RETURN OBJECT_CONSTRUCT(
        'same_specimen_conflicts', v_same_spec_conflicts,
        'cross_specimen_discordant', v_cross_spec_discordant,
        'support_links_added', v_links,
        'reconciled_at', TO_VARCHAR(CURRENT_TIMESTAMP(), 'YYYY-MM-DD"T"HH24:MI:SS')
    );
END;
$$;
-- ===== END tasks/reconcile_evidence.sql (procedure part) =====

-- ===== BEGIN tasks/orchestrator.sql (procedure part) =====
-- =============================================================================
-- STEP 16c - TASK saarthi_orchestrator (the "task on top")
-- =============================================================================
-- SPEC.md line 3 / hackathon "headline bonus": "one skill per process plus a
-- task on top which orchestrates between the three of them". This is that
-- task. It sequences the four operational steps that produce a fresh answer
-- state for every patient encounter:
--
--   parse_documents    -> extract text + pages from any new PDF (patient or
--                         reference corpus)
--   chunk_documents    -> split parsed pages into search chunks and populate
--                         DOC_CHUNK (synchronous, not a DT: RAP-on-source
--                         made background refresh return zero rows, found
--                         live and documented in evidence/coco/execution.yaml)
--   extract_assertions -> R7 two-pass typed extraction over new DOC_CHUNK rows
--   reconcile_evidence -> conflicts, cross-specimen links, assertion->event 'supports' links
--   refresh_readiness  -> re-evaluate all 16 gates and MERGE into READINESS_STATE
--
-- Everything each step needs is already present as a procedure; the task
-- exists so a coordinator can hit "refresh" once and the whole chain runs
-- deterministically in order, not as four independent schedules whose
-- interleaving would be racy.
--
-- Scheduled 30 MINUTE by default. Downstream tasks (TASK_PARSE_DOCUMENTS,
-- TASK_EXTRACT_ASSERTIONS) already have their own stream-triggered schedules
-- for real-time ingestion; this orchestrator is the "on-demand full sweep"
-- path.

CREATE OR REPLACE PROCEDURE SAARTHI.OPERATIONAL.orchestrator_proc()
  RETURNS VARIANT
  LANGUAGE SQL
  COMMENT = 'Task on top - orchestrates parse -> chunk -> extract -> refresh in order.'
  EXECUTE AS OWNER
AS
$$
DECLARE
    v_parsed VARIANT;
    v_chunked VARIANT;
    v_extracted VARIANT;
    v_reconciled VARIANT;
    v_refreshed VARIANT;
    v_error VARCHAR;
BEGIN
    v_parsed := (CALL SAARTHI.OPERATIONAL.parse_documents_proc());
    v_chunked := (CALL SAARTHI.OPERATIONAL.chunk_documents_proc());
    v_extracted := (CALL SAARTHI.OPERATIONAL.extract_assertions_proc());
    -- reconcile_evidence writes the EVIDENCE_LINK rows (assertion -> event 'supports') that let a
    -- gate cite the verified document span behind its number. It was only reachable as a child of
    -- TASK_EXTRACT_ASSERTIONS, so an on-demand sweep left every gate without document provenance.
    v_reconciled := (CALL SAARTHI.OPERATIONAL.reconcile_evidence_proc());
    v_refreshed := (CALL SAARTHI.OPERATIONAL.refresh_readiness_proc());

    RETURN OBJECT_CONSTRUCT(
        'orchestration_at', TO_VARCHAR(CURRENT_TIMESTAMP(), 'YYYY-MM-DD"T"HH24:MI:SS'),
        'parse', :v_parsed,
        'chunk', :v_chunked,
        'extract', :v_extracted,
        'reconcile', :v_reconciled,
        'readiness', :v_refreshed
    );
EXCEPTION
    WHEN OTHER THEN
        RETURN OBJECT_CONSTRUCT(
            'error', SQLERRM,
            'sqlcode', SQLCODE,
            'orchestration_at', TO_VARCHAR(CURRENT_TIMESTAMP(), 'YYYY-MM-DD"T"HH24:MI:SS')
        );
END;
$$;
-- ===== END tasks/orchestrator.sql (procedure part) =====

-- ===== BEGIN governance/03_grants.sql (section) =====
-- =============================================================================
-- STEP 9 - Grants   *** RED STEP ***
-- =============================================================================
-- The app role gets NO USAGE on either search service (created in step 17).
-- Retrieval happens only through owner's-rights procedures (step 14).
-- F7: "the app role has no USAGE" is FALSE while secondary roles are active -
-- a secondary ACCOUNTADMIN satisfies the privilege check through the back
-- door and the GRANT audit still looks correct. Every app session MUST run
-- USE SECONDARY ROLES NONE, or authenticate as a dedicated service user.
-- This file only ever grants what SAARTHI_APP needs to run the Streamlit UI
-- and call procedures - it never grants USAGE on PATIENT_DOC_SEARCH or
-- REFERENCE_DOC_SEARCH, and no later step may add that grant.

GRANT USAGE ON DATABASE SAARTHI TO ROLE SAARTHI_APP;
GRANT USAGE ON DATABASE SAARTHI TO ROLE SAARTHI_COORDINATOR;
GRANT USAGE ON DATABASE SAARTHI TO ROLE SAARTHI_ONCOLOGIST;
GRANT USAGE ON DATABASE SAARTHI TO ROLE SAARTHI_NAVIGATOR;
GRANT USAGE ON DATABASE SAARTHI TO ROLE SAARTHI_JUDGE;

GRANT USAGE ON ALL SCHEMAS IN DATABASE SAARTHI TO ROLE SAARTHI_APP;
GRANT USAGE ON FUTURE SCHEMAS IN DATABASE SAARTHI TO ROLE SAARTHI_APP;

-- Public APIs only. Revoke inherited broad grants before applying the allowlist.
REVOKE USAGE ON FUTURE PROCEDURES IN SCHEMA SAARTHI.OPERATIONAL FROM ROLE SAARTHI_APP;
REVOKE USAGE ON ALL PROCEDURES IN SCHEMA SAARTHI.OPERATIONAL FROM ROLE SAARTHI_APP;
GRANT USAGE ON PROCEDURE SAARTHI.OPERATIONAL.ANSWER_GATEWAY_REFUSAL(VARCHAR) TO ROLE SAARTHI_APP;
GRANT USAGE ON PROCEDURE SAARTHI.OPERATIONAL.ASK_SAARTHI(VARCHAR) TO ROLE SAARTHI_APP;
GRANT USAGE ON PROCEDURE SAARTHI.OPERATIONAL.BIND_PATIENT(VARCHAR) TO ROLE SAARTHI_APP;
GRANT USAGE ON PROCEDURE SAARTHI.OPERATIONAL.CLASSIFY_QUESTION(VARCHAR) TO ROLE SAARTHI_APP;
GRANT USAGE ON PROCEDURE SAARTHI.OPERATIONAL.COHORT_QUERY(VARCHAR) TO ROLE SAARTHI_APP;
GRANT USAGE ON PROCEDURE SAARTHI.OPERATIONAL.CREATE_REVIEW_TASK(VARCHAR,VARCHAR,VARCHAR,VARCHAR) TO ROLE SAARTHI_APP;
GRANT USAGE ON PROCEDURE SAARTHI.OPERATIONAL.GET_CHANGES(VARCHAR,VARCHAR) TO ROLE SAARTHI_APP;
GRANT USAGE ON PROCEDURE SAARTHI.OPERATIONAL.GET_PATIENT_FACTS(VARCHAR,VARCHAR) TO ROLE SAARTHI_APP;
GRANT USAGE ON PROCEDURE SAARTHI.OPERATIONAL.GET_READINESS(VARCHAR,VARCHAR) TO ROLE SAARTHI_APP;
GRANT USAGE ON PROCEDURE SAARTHI.OPERATIONAL.GET_TIMELINE(VARCHAR) TO ROLE SAARTHI_APP;
