-- ===== BEGIN governance/03_grants.sql (agent/mcp, guarded) =====
-- Agent + MCP server access. Snowflake docs are explicit that USAGE on an
-- MCP SERVER does NOT confer USAGE on the underlying tools; ASK procedure grants are
-- required for a caller to invoke the agent via MCP. SAARTHI_APP is the
-- effective role for every Streamlit / Cortex Agent REST call and for
-- external MCP clients that authenticate as a role linked to SAARTHI_APP.
--
-- No secondary-role trap here either: the agent's RAP (patient_scope on
-- CURRENT_USER) still fires regardless of which role wraps the session,
-- and USE SECONDARY ROLES NONE remains mandatory app-side.
-- N4-01: the bundle does not create the agent or the MCP server. A missing object must not stop
-- Run all; the block returns 'skipped ...' (read the result) and the grant is re-run after the object exists.

EXECUTE IMMEDIATE $$
BEGIN
    REVOKE USAGE ON AGENT SAARTHI.OPERATIONAL.SAARTHI_AGENT FROM ROLE SAARTHI_APP;
    RETURN 'revoke: SAARTHI_AGENT';
EXCEPTION
    WHEN OTHER THEN
        RETURN 'skipped SAARTHI_AGENT (object absent or not grantable): ' || SQLERRM;
END;
$$;

EXECUTE IMMEDIATE $$
BEGIN
    GRANT USAGE ON MCP SERVER SAARTHI.OPERATIONAL.SAARTHI_MCP TO ROLE SAARTHI_APP;
    RETURN 'grant: SAARTHI_MCP';
EXCEPTION
    WHEN OTHER THEN
        RETURN 'skipped SAARTHI_MCP (object absent or not grantable): ' || SQLERRM;
END;
$$;

-- ===== END governance/03_grants.sql (agent/mcp, guarded) =====

-- VERIFY: SAARTHI_APP must hold USAGE on the OPERATIONAL procedures (grants run BEFORE the tasks below).
SHOW GRANTS TO ROLE SAARTHI_APP;

